import React, { useState } from "react";
import { useForm, SubmitHandler } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { db } from "../../firebaseConfig";
import { collection, addDoc, Timestamp } from "firebase/firestore";
import emailjs from "@emailjs/browser";
import { buildEmailMessage, getEmailJsConfig } from "../../utils/emailjs";

const schema: yup.ObjectSchema<FormData> = yup.object({
  fullName: yup.string().required("Full name is required"),
  email: yup.string().email("Invalid email").required("Email is required"),
  message: yup.string().required("Message is required"),
}) as yup.ObjectSchema<FormData>;

type FormData = {
  fullName: string;
  email: string;
  message: string;
};

export default function ContactForm() {
  const [sending, setSending] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const { t } = useTranslation();

  const {
    register,
    handleSubmit,
    reset,
    formState: { errors },
  } = useForm<FormData>({
    resolver: yupResolver(schema),
    mode: "onChange",
    defaultValues: {
      fullName: "",
      email: "",
      message: "",
    },
  });

  const onSubmit: SubmitHandler<FormData> = async (data) => {
    setSending(true);
    try {
      await addDoc(collection(db, "contactMessages"), {
        ...data,
        createdAt: Timestamp.now(),
      });

      const emailConfig = getEmailJsConfig();

      if (!emailConfig) {
        console.error("Missing EmailJS environment variables");
        setSending(false);
        return;
      }

      const emailMessage = buildEmailMessage("contact", {
        fullName: data.fullName,
        email: data.email,
        message: data.message,
      });

      await emailjs.send(
        emailConfig.serviceId,
        emailConfig.templateId,
        emailMessage,
        emailConfig.publicKey
      );

      reset();
      setSubmitted(true);
    } catch (error) {
      console.error("Error submitting form:", error);
    } finally {
      setSending(false);
    }
  };

  return (
    <form onSubmit={handleSubmit(onSubmit)} className="w-full sm:w-[400px]">
      {submitted ? (
        <div className="flex flex-col items-center mt-8 rounded-2xl border border-purplesemilight/40 bg-primary/70 p-6 text-center shadow-sm supports-[backdrop-filter]:bg-purplesemilight/20 supports-[backdrop-filter]:backdrop-blur">
          <p className="text-light text-base sm:text-lg font-semibold mb-2">
            {t("contact.form.thankYou") || "Thank you for your message!"}
          </p>
          <p className="text-light/70 text-sm sm:text-base mb-4">
            {t("contact.form.confirmation") || "We will get back to you shortly."}
          </p>
          <button
            onClick={() => {
              reset();
              setSubmitted(false);
            }}
            type="button"
            className="w-full rounded-full bg-purplesemilight px-5 py-2.5 text-light text-sm sm:text-base text-center transition duration-[400ms] hover:opacity-90"
          >
            {t("contact.form.backToForm") || "Back to Form"}
          </button>
        </div>
      ) : (
        <>
          <div className="text-sm sm:text-base text-light/70 mb-6">
            {t("contact.subtitle")}
          </div>

          {/* Full Name */}
          <label className={styles.label} htmlFor="contact-full-name">
            {t("contact.form.name") || "Name"}
          </label>
          <input
            id="contact-full-name"
            type="text"
            autoComplete="name"
            className={styles.input}
            aria-invalid={!!errors.fullName}
            {...register("fullName")}
          />
          {errors.fullName?.message ? (
            <p className={styles.error}>{errors.fullName.message}</p>
          ) : null}

          {/* Email */}
          <label className={`${styles.label} mt-4`} htmlFor="contact-email">
            {t("contact.form.email") || "Email"}
          </label>
          <input
            id="contact-email"
            type="email"
            autoComplete="email"
            className={styles.input}
            aria-invalid={!!errors.email}
            {...register("email")}
          />
          {errors.email?.message ? (
            <p className={styles.error}>{errors.email.message}</p>
          ) : null}

          {/* Message */}
          <label className={`${styles.label} mt-4`} htmlFor="contact-message">
            {t("contact.form.message") || "Message"}
          </label>
          <textarea
            id="contact-message"
            rows={4}
            className={`${styles.input} ${styles.textarea}`}
            aria-invalid={!!errors.message}
            {...register("message")}
          />
          {errors.message?.message ? (
            <p className={styles.error}>{errors.message.message}</p>
          ) : null}

          <div className="mt-6">
            <button
              type="submit"
              disabled={sending}
              className={`${styles.submit} ${sending ? "opacity-60 cursor-not-allowed" : ""}`}
            >
              {sending
                ? t("contact.form.sending") || "Sending..."
                : t("contact.form.submit") || "Send"}
            </button>
          </div>
        </>
      )}
    </form>
  );
}

const styles = {
  label: "block text-sm text-light/80",
  input:
    "mt-2 w-full rounded-xl border border-purplesemilight/50 bg-primary/70 px-4 py-3 text-sm sm:text-base text-light placeholder:text-purplelight/60 focus:outline-none focus:border-secondary focus:ring-2 focus:ring-secondary/40 transition",
  textarea: "min-h-[120px] resize-y",
  error: "mt-2 text-xs text-purplelight",
  submit:
    "w-full rounded-full bg-secondary px-6 py-3 text-light text-sm sm:text-base text-center transition duration-[400ms] hover:opacity-90",
};
