import React, { useEffect } from "react";
import Layout from "./layout";
import data from "../data/data.json";
import type { Company } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { graphql, type PageProps, Link } from "gatsby";
import images from "../images";
import SEO from "../components/seo";

import { BiLogoInstagramAlt } from "react-icons/bi";
import {
  FaSquareFacebook,
  FaSquareWhatsapp,
  FaSquarePhone,
  FaLinkedin,
} from "react-icons/fa6";
import { MdEmail } from "react-icons/md";
import { ImLocation2 } from "react-icons/im";
import ContactForm from "../components/contactForm";

const info: Company = data[0];

const ContactPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();

  useEffect(() => {
    document.body.style.backgroundImage = `url(${images.bg.src})`;
    document.body.style.backgroundSize = "cover";
    document.body.style.backgroundPosition = "center";
    document.body.style.backgroundRepeat = "no-repeat";

    return () => {
      document.body.style.backgroundImage = "";
      document.body.style.backgroundSize = "";
      document.body.style.backgroundPosition = "";
      document.body.style.backgroundRepeat = "";
    };
  }, []);

  const mailSubject = encodeURIComponent(t("contact.meta.emailSubject") || "");
  const mailBody = encodeURIComponent(t("contact.meta.emailBody") || "");
  const mailto = `mailto:${info.email}?subject=${mailSubject}&body=${mailBody}`;

  const tel = `tel:${info.phone}`;
  // Nota: en tu data.json, whatsapp ya parece venir como URL (https://wa.me/...)
  // Para evitar duplicar "https://wa.me/", lo usamos tal cual:
  const whatsappHref = info.whatsapp;

  return (
    <Layout data={info} bgImage={images.bg_carousel_1.src}>
      <SEO
        data={info}
        titleKey="contact.metaTitle"
        descriptionKey="contact.metaDescription"
        pathname="/contact/"
        schemaType="ProfessionalService"
      />

      <section className={styles.wrapper}>
        {/* HERO */}
        <header className="text-center">
          <h1 className={styles.title}>{t("contact.hero.title")}</h1>
          <p className={styles.subtitle}>{t("contact.hero.subtitle")}</p>

          <div className={styles.ctaRow}>
            <a
              href={whatsappHref}
              target="_blank"
              rel="noreferrer"
              className={`${styles.ctaButton} bg-secondary`}
            >
              {t("contact.hero.primaryCta")}
            </a>

            <a href={mailto} className={`${styles.ctaButton} bg-purplesemilight`}>
              {t("contact.hero.secondaryCta")}
            </a>
          </div>

          <p className={styles.helper}>{t("contact.hero.helper")}</p>
        </header>

        {/* QUICK OPTIONS */}
        <section className="mt-10">
          <div className={styles.cardsGrid}>
            <article className={`${styles.card} gradient-reverse`}>
              <h2 className={styles.cardTitle}>{t("contact.cards.audit.title")}</h2>
              <p className={styles.cardText}>{t("contact.cards.audit.text")}</p>
              <a href={mailto} className={styles.cardLink}>
                {t("contact.cards.audit.cta")}
              </a>
            </article>

            <article className={`${styles.card} gradient`}>
              <h2 className={styles.cardTitle}>{t("contact.cards.quote.title")}</h2>
              <p className={styles.cardText}>{t("contact.cards.quote.text")}</p>
              <Link to="/services/" className={styles.cardLink}>
                {t("contact.cards.quote.cta")}
              </Link>
            </article>

            <article className={`${styles.card} gradient-reverse`}>
              <h2 className={styles.cardTitle}>{t("contact.cards.maintenance.title")}</h2>
              <p className={styles.cardText}>{t("contact.cards.maintenance.text")}</p>
              <Link to="/services/maintenance/" className={styles.cardLink}>
                {t("contact.cards.maintenance.cta")}
              </Link>
            </article>
          </div>
        </section>

        {/* CONTACT DETAILS */}
        <article className={styles.infoBlock}>
          <div className={`${styles.socialContainer} gradient-reverse`}>
            <h3 className={styles.sectionTitle}>{t("contact.details.title")}</h3>


            <section className={`${styles.links} flex-col`}>
              <a href={tel} className={styles.inlineLinks}>
                <FaSquarePhone />
                <span>{info.phone}</span>
              </a>

              <a href={mailto} className={styles.inlineLinks}>
                <MdEmail />
                <span>{info.email}</span>
              </a>

              <div className={styles.inlineLinks}>
                <ImLocation2 />
                <span>
                  {info.city}, {info.province}, {info.country}
                </span>
              </div>

              <p className={styles.smallNote}>{t("contact.details.note")}</p>
            </section>


            <h3 className={`${styles.sectionTitle} mt-12`}>{t("contact.social.title")}</h3>
            <p className={styles.smallNote}>{t("contact.social.note")}</p>

            <section className={styles.links}>
              <a href={info.instagram} target="_blank" rel="noreferrer" className={styles.iconWrapper}>
                <BiLogoInstagramAlt className={styles.icon} />
              </a>
              <a href={info.facebook} target="_blank" rel="noreferrer" className={styles.iconWrapper}>
                <FaSquareFacebook className={styles.icon} />
              </a>
              <a href={whatsappHref} target="_blank" rel="noreferrer" className={styles.iconWrapper}>
                <FaSquareWhatsapp className={styles.icon} />
              </a>
              <a href={info.linkedin} target="_blank" rel="noreferrer" className={styles.iconWrapper}>
                <FaLinkedin className={styles.icon} />
              </a>
            </section>

          </div>

          <div className={`${styles.socialContainer} gradient`}>

            <ContactForm />




          </div>
        </article>

        {/* SEO-friendly closing */}
        <section className="mt-12 text-center">
          <h2 className={styles.sectionTitleAlt}>{t("contact.bottom.title")}</h2>
          <p className={styles.bottomText}>{t("contact.bottom.text")}</p>
        </section>
      </section>
    </Layout>
  );
};

export default ContactPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  wrapper: "w-full max-w-4xl mx-auto text-center text-purplelight px-4 sm:px-0 py-10",
  title: "text-3xl sm:text-5xl poppins-bold text-light",
  subtitle: "text-lg sm:text-2xl poppins-regular text-light/90 mt-4",
  helper: "text-sm sm:text-base text-light/70 mt-6 max-w-3xl mx-auto",
  ctaRow: "mx-auto mt-8 flex flex-col sm:flex-row items-center justify-center gap-3",

  ctaButton:
    "rounded-full px-5 py-2.5 text-light text-center transition duration-[400ms] hover:opacity-90",

  cardsGrid: "grid grid-cols-1 sm:grid-cols-3 gap-4",
  card: "rounded-3xl p-6 sm:p-8 text-left",
  cardTitle: "text-xl font-semibold text-light",
  cardText: "text-sm sm:text-base text-light/80 mt-3 leading-relaxed",
  cardLink: "inline-block mt-5 text-sm text-light underline underline-offset-4 hover:opacity-90",

  infoBlock: "flex flex-col sm:flex-row justify-center gap-4 mt-10",
  socialContainer: "rounded-3xl py-10 px-8 text-left",
  sectionTitle: "text-2xl poppins-regular text-light",
  sectionTitleAlt: "text-2xl sm:text-3xl poppins-regular text-verde",
  smallNote: "text-sm text-light/70 mt-4 leading-relaxed",

  links: "hidden sm:flex gap-4 text-purplesemilight justify-start mt-6 text-2xl",
  iconWrapper:
    "block p-4 rounded-full bg-purplelight hover:bg-purplesemilight hover:text-purplelight transition duration-[600ms]",
  inlineLinks: "flex flex-row items-center gap-2 text-light/90 text-base",
  icon: "text-[3rem] sm:text-[4rem]",

  bottomText: "text-sm sm:text-base text-light/70 mt-4 max-w-3xl mx-auto",
};
